  ('a1aa72bd-3f62-46a5-9109-bc23d06f2892', 'f8a9b0c1-2d3e-4f83-8a33-4b5c6d7e8f13', '23e0e972-151d-48d6-9fe5-4857ba17a48f', 'subtopic'::public.curated_course_node_type, 'Form review and irregular preterites', 'Secure the high-frequency forms that make narration possible under real-time speaking and writing conditions.', 0),
