set
  title = 'Intermediate Spanish I',
  goal = 'Intermediate Spanish I',
  summary = 'Intermediate Spanish I develops students'' ability to narrate in the past, express wishes and uncertainty, discuss current issues, read short prose, and write organized paragraphs in Spanish. The course treats grammar as a communicative resource: students learn forms, then use them to tell stories, interpret authentic materials, exchange opinions, and revise their own language with increasing independence.',
  data = $isp1json${"slug": "intermediate-spanish-i", "title": "Intermediate Spanish I", "description": "Intermediate Spanish I develops students' ability to narrate in the past, express wishes and uncertainty, discuss current issues, read short prose, and write organized paragraphs in Spanish. The course treats grammar as a communicative resource: students learn forms, then use them to tell stories, interpret authentic materials, exchange opinions, and revise their own language with increasing independence.", "topics": [{"id": "23e0e972-151d-48d6-9fe5-4857ba17a48f", "type": "topic", "title": "Preterite versus Imperfect", "description": "This unit turns past-tense forms into narrative control. Students learn to choose between completed events, background description, habitual action, interrupted action, and point-of-view shifts so that stories sound purposeful rather than translated word by word.", "children": [{"id": "a1aa72bd-3f62-46a5-9109-bc23d06f2892", "type": "subtopic", "title": "Form review and irregular preterites", "children": [{"id": "c9fd8f88-33e7-45fe-9bb7-ed0737629bff", "type": "concept", "title": "regular preterite endings"}, {"id": "a0d42d55-1636-421f-8f5d-8a9fd00c8294", "type": "concept", "title": "orthographic changes"}, {"id": "8d593ed9-0acf-4a97-8d7a-008e5a684e26", "type": "concept", "title": "ir, ser, hacer, tener, estar, poder, poner, decir"}], "description": "Secure the high-frequency forms that make narration possible under real-time speaking and writing conditions."}, {"id": "89c40ade-520b-448c-8758-b95a9224d98f", "type": "subtopic", "title": "Imperfect formation and meaning", "children": [{"id": "8875d17f-6071-4df7-90b8-0aad4118af2a", "type": "concept", "title": "-aba and -ía endings"}, {"id": "f47f79ad-e1b2-4e3e-8a7d-2aa84cdf70f6", "type": "concept", "title": "ser, ir, ver"}, {"id": "ba8bb9af-33e9-4c01-894f-260eec5e5f9f", "type": "concept", "title": "age, time, weather, feelings, descriptions"}], "description": "Use the imperfect for setting scenes, describing ongoing states, and narrating repeated actions."}, {"id": "9e408308-eb5a-4bba-9a9e-93a240357587", "type": "subtopic", "title": "Aspect and narrative choice", "children": [{"id": "8289ccb6-7319-499a-8329-1a7e3dba8773", "type": "concept", "title": "completed events"}, {"id": "85c7ea2d-b6fb-4719-b5d0-ebcb1d47e59f", "type": "concept", "title": "background information"}, {"id": "ab8d27b6-ea1d-47e2-ba16-73473a964e0c", "type": "concept", "title": "habitual past"}, {"id": "e1662767-32f8-4eea-bffc-fe98372b273f", "type": "concept", "title": "interruption frames"}], "description": "Understand that tense choice is a meaning choice, not a translation trick."}, {"id": "8bd0a9c5-21cf-4957-93cf-520176308821", "type": "subtopic", "title": "Narrative sequencing", "children": [{"id": "6be847bf-bb4d-48cc-a3bc-f32585392dca", "type": "concept", "title": "time markers"}, {"id": "f08699b8-e7d6-4d41-9a33-878692f1b4c7", "type": "concept", "title": "connectors"}, {"id": "113445c1-ec82-4b18-ae39-2905968140ca", "type": "concept", "title": "paragraph unity"}, {"id": "194f65d0-3d75-40e3-9646-8cb6ae942c1e", "type": "concept", "title": "spoken storytelling"}], "description": "Build coherent accounts of experiences, memories, news events, and cultural stories."}]}, {"id": "b07a58be-6b53-42f5-b9f6-e6ed8eff1e15", "type": "topic", "title": "Present Subjunctive", "description": "This unit introduces the subjunctive as a tool for expressing subjectivity, influence, doubt, emotion, and possibility. Students move from formulaic triggers to meaningful communication about hopes, obligations, opinions, and uncertain outcomes.", "children": [{"id": "e3d28972-c0a1-4049-90fd-06d95b801eb9", "type": "subtopic", "title": "Formation of the present subjunctive", "children": [{"id": "aa10df90-9d9e-4d2f-958c-b8c3a5ba8d29", "type": "concept", "title": "yo-form base"}, {"id": "daa734e9-4dff-4416-9faa-720fdbb7a800", "type": "concept", "title": "opposite vowel endings"}, {"id": "7e8b6109-c813-41c8-ba1e-0b7b25094846", "type": "concept", "title": "dar, estar, ir, saber, ser"}, {"id": "83bc6970-c73b-4167-a76d-a8eddccfcb73", "type": "concept", "title": "spelling changes"}], "description": "Develop automatic control of regular, stem-changing, and irregular forms."}, {"id": "787142e4-59a1-4075-87d5-1279cf46929b", "type": "subtopic", "title": "Noun clauses and influence", "children": [{"id": "48bbb5c6-00fd-4de9-b7f1-04a511a7dbcb", "type": "concept", "title": "querer que"}, {"id": "d2ef49ef-8370-4f9c-96c0-d4ee9544954c", "type": "concept", "title": "pedir que"}, {"id": "9fb4fb96-be06-46d3-8321-b8a3309d3724", "type": "concept", "title": "recomendar que"}, {"id": "db038a41-946a-462b-a7fb-cee1c9f5779d", "type": "concept", "title": "es necesario que"}], "description": "Use the subjunctive to say what someone wants, recommends, requests, or requires."}, {"id": "983eb266-2d3f-495b-b47b-cd0c7f3fd67e", "type": "subtopic", "title": "Emotion and evaluation", "children": [{"id": "b16e9ee3-20a8-4237-b659-2b452ad73e77", "type": "concept", "title": "me alegra que"}, {"id": "3b7d75fb-c5c7-4ad9-af27-082f8e87dbc5", "type": "concept", "title": "es bueno que"}, {"id": "6fb9fa3a-6b4b-41ef-92cb-35bdb94a863a", "type": "concept", "title": "sentir que"}, {"id": "e88a6918-1691-46ef-b958-0b208d4b3892", "type": "concept", "title": "lamentar que"}], "description": "Express reactions to actions and situations with accuracy and nuance."}, {"id": "a32c4bae-c0bf-4cee-8971-9dbdbd033d96", "type": "subtopic", "title": "Doubt, denial, and uncertainty", "children": [{"id": "e36c5ed4-4e63-4044-9f07-ca0e4e671d70", "type": "concept", "title": "dudar que"}, {"id": "912997ff-5d78-4c50-b4a2-32f1986e82d5", "type": "concept", "title": "no creer que"}, {"id": "652e8575-0476-476e-8b47-ce5d12400a73", "type": "concept", "title": "no es cierto que"}, {"id": "b2b15ca0-7c03-4d66-b8aa-b086c3565af5", "type": "concept", "title": "tal vez and quizas"}], "description": "Distinguish between claims presented as real and claims presented as doubtful."}]}, {"id": "f6041bcf-e510-4768-9ece-7ecee1c52b09", "type": "topic", "title": "Indicative and Subjunctive Contrasts", "description": "Students deepen grammatical judgment by comparing indicative and subjunctive choices in authentic contexts. The goal is not memorizing trigger lists, but learning how mood signals the speaker's stance toward information.", "children": [{"id": "53328f62-e19a-4c84-a637-efcc79f5331b", "type": "subtopic", "title": "Reality, assertion, and speaker stance", "children": [{"id": "cd94979b-be42-44b0-8a44-5663d94b996c", "type": "concept", "title": "creer que"}, {"id": "5db335ce-93fe-40de-b429-55e074e4a2d2", "type": "concept", "title": "saber que"}, {"id": "7d96be05-39ca-4f1d-be03-0ad2862a11d1", "type": "concept", "title": "es cierto que"}, {"id": "cc1a940a-4f3d-416d-9605-a3fa5981abf2", "type": "concept", "title": "evidence and certainty"}], "description": "Choose the indicative for information presented as known, asserted, or directly experienced."}, {"id": "38538938-8aca-4b45-8b27-f2cc9fcdd406", "type": "subtopic", "title": "Uncertainty and non-assertion", "children": [{"id": "2c94a5fb-a75f-44ee-9f89-8a5faae0de60", "type": "concept", "title": "buscar a alguien que"}, {"id": "90943123-a6ab-48dd-a630-d73ef6d0d385", "type": "concept", "title": "no hay nadie que"}, {"id": "471cd06b-e6bc-466c-8053-e459ab1501fa", "type": "concept", "title": "cuando with future reference"}, {"id": "53e9dee0-f607-4869-84a9-8be2044ff2ce", "type": "concept", "title": "aunque contrasts"}], "description": "Use the subjunctive when the clause is desired, hypothetical, disputed, or not yet realized."}, {"id": "1d2ba27e-cfc5-46c5-a711-9e1b8ac19d79", "type": "subtopic", "title": "Mood in context", "children": [{"id": "f4e3e662-6d1c-4a98-9d7d-4903ef1e0972", "type": "concept", "title": "news excerpts"}, {"id": "8fee6df7-7f0b-4359-80a0-7f161f9dd191", "type": "concept", "title": "advice columns"}, {"id": "f72c2aa6-279f-483b-a6d4-bd0a11f0650f", "type": "concept", "title": "interviews"}, {"id": "7b248fc9-8715-4569-b779-73bddfeb6ff3", "type": "concept", "title": "cultural commentary"}], "description": "Analyze short readings and conversations to see how mood shapes tone and meaning."}, {"id": "82b601e0-6eb8-4ed7-ad31-ae7c03180f4a", "type": "subtopic", "title": "Editing for mood accuracy", "children": [{"id": "33a7be6c-fa72-49a2-a693-dbf6ff8666d3", "type": "concept", "title": "self-editing marks"}, {"id": "50e29826-3925-4c5d-9fef-119f512de540", "type": "concept", "title": "peer review"}, {"id": "d582eee6-590c-4669-a3a2-fcbda4a05b84", "type": "concept", "title": "grammar logs"}, {"id": "173a7562-4adc-4d57-b60b-e8f42cb8342b", "type": "concept", "title": "sentence combining"}], "description": "Revise paragraphs by explaining the reason for each mood choice."}]}, {"id": "c6d5ac77-0327-403a-a374-4726b8523f30", "type": "topic", "title": "Por and Para", "description": "This unit helps students replace memorized English equivalents with conceptual control. Students learn how por and para organize cause, purpose, destination, exchange, duration, perspective, and movement through space.", "children": [{"id": "8e106ce2-9b75-47e7-9f2b-b7cb49961340", "type": "subtopic", "title": "Purpose, destination, and deadlines", "children": [{"id": "2a658756-7b8c-4a92-afe8-066249438ec3", "type": "concept", "title": "para + infinitive"}, {"id": "1d98b9ef-9b5c-45f9-b840-e19d647275fc", "type": "concept", "title": "para alguien"}, {"id": "319caf57-b6d5-4372-a1f9-fa28e071e637", "type": "concept", "title": "para el viernes"}, {"id": "170892b7-0573-4d42-a58f-4f93158962c6", "type": "concept", "title": "para mi carrera"}], "description": "Use para to talk about goals, recipients, intended uses, and time limits."}, {"id": "da4dc107-d881-4d68-80f0-46c3db3a630e", "type": "subtopic", "title": "Cause, exchange, and duration", "children": [{"id": "94fda214-d9b4-4945-a8b9-02a1485d95c6", "type": "concept", "title": "por eso"}, {"id": "b014cb40-a4f3-42b8-af33-f664e44f01b6", "type": "concept", "title": "por dos horas"}, {"id": "c0fe171f-b2d0-44c8-af39-735e8ba52d09", "type": "concept", "title": "por el parque"}, {"id": "4629b4f3-7ceb-4203-98a3-f7e38d1dfa78", "type": "concept", "title": "por cien dolares"}], "description": "Use por for motives, substitutions, movement through places, rates, and lengths of time."}, {"id": "a0e28353-6a1b-4e32-bbb2-8d319719d848", "type": "subtopic", "title": "Common expressions and idioms", "children": [{"id": "4b6d9b64-f654-43f8-84fc-f6054d471296", "type": "concept", "title": "por supuesto"}, {"id": "1213f4c9-87f4-474a-976b-ad60582650d7", "type": "concept", "title": "para siempre"}, {"id": "adafa609-848c-4fac-89d7-e1999ecba9bc", "type": "concept", "title": "por lo tanto"}, {"id": "4a65c08f-96bd-4ff5-a765-b94cb993075e", "type": "concept", "title": "estar por/para"}], "description": "Recognize high-frequency phrases that carry meaning beyond literal preposition rules."}, {"id": "7e8df1f1-d90f-463b-923b-abcbf436c86a", "type": "subtopic", "title": "Contrastive practice in speech and writing", "children": [{"id": "bea65883-4b64-4214-9abc-07d9d57fe529", "type": "concept", "title": "travel plans"}, {"id": "31eca433-9b55-4f1b-86ce-1a258924d70c", "type": "concept", "title": "service learning"}, {"id": "e3af8759-f2a7-4d89-bc97-4b3753471e58", "type": "concept", "title": "career goals"}, {"id": "8cb05318-f043-467d-a8d2-090b3b4a10d7", "type": "concept", "title": "community issues"}], "description": "Use por and para in meaningful tasks rather than isolated fill-ins."}]}, {"id": "88af4fbf-48ec-4dbe-b930-e7f6f8d4d482", "type": "topic", "title": "Future and Conditional", "description": "Students learn to discuss prediction, planning, probability, courtesy, speculation, and hypothetical outcomes. The unit connects form accuracy with everyday and academic communication about what will happen, what might happen, and what one would do.", "children": [{"id": "fbb4e63a-8e93-4028-80ae-4e76e11706ae", "type": "subtopic", "title": "Future tense forms and irregular stems", "children": [{"id": "5d5365b2-e602-4fdf-b5fc-426e913e925f", "type": "concept", "title": "infinitive endings"}, {"id": "8d5a59a8-237a-4271-98ad-b624729db991", "type": "concept", "title": "decir, hacer, poder, poner, querer"}, {"id": "7f0c2cda-b3f1-4b63-882e-7ba1e0944042", "type": "concept", "title": "future time markers"}], "description": "Build accurate future-tense sentences for plans, predictions, and commitments."}, {"id": "124d100b-2ec8-4328-8e28-aab81b13e57d", "type": "subtopic", "title": "Conditional forms and polite expression", "children": [{"id": "60094e41-c960-47a3-bc4d-e3a6b952ed40", "type": "concept", "title": "me gustaria"}, {"id": "37e5575d-6cf1-4ea0-a818-4950474b8d8a", "type": "concept", "title": "podria"}, {"id": "a9c51505-f911-4852-976c-e893b6a2d375", "type": "concept", "title": "deberia"}, {"id": "41045b70-f939-474f-957f-5a24230c75b4", "type": "concept", "title": "seria mejor"}], "description": "Use the conditional for requests, preferences, advice, and imagined situations."}, {"id": "5e9a1318-be97-44fa-b834-0bfaeb9552d6", "type": "subtopic", "title": "Probability and conjecture", "children": [{"id": "247a9613-30bc-44c7-b92e-5e5d310f1aab", "type": "concept", "title": "sera"}, {"id": "074f0703-a232-4064-975d-3cfe0e6af84c", "type": "concept", "title": "tendra"}, {"id": "a349bfa9-3372-480b-8331-7ed12eaf9a2f", "type": "concept", "title": "serian"}, {"id": "d5ff75cb-40f6-4ae1-b86a-4872dee31242", "type": "concept", "title": "habria"}], "description": "Interpret future and conditional forms that express likelihood rather than time."}, {"id": "19a362b6-3996-4d77-a679-b14b542bd162", "type": "subtopic", "title": "Planning and problem-solving tasks", "children": [{"id": "7ccc6803-be51-42a0-b13f-cf81b2898e8b", "type": "concept", "title": "itineraries"}, {"id": "8f7afee3-42b2-48f0-9f79-6db78f01f0ee", "type": "concept", "title": "recommendations"}, {"id": "7987b216-7074-4589-95b7-a89865bab766", "type": "concept", "title": "scenario planning"}, {"id": "2eca05b5-bd68-430a-abb6-731bf3973aaa", "type": "concept", "title": "oral negotiation"}], "description": "Apply both tenses in projects about travel, careers, sustainability, and community life."}]}, {"id": "2e3936e7-202a-435c-bcc2-9bc4a7d4ce7a", "type": "topic", "title": "Relative Pronouns", "description": "This unit teaches students to connect ideas with precision. Relative pronouns support more mature sentences, richer descriptions, smoother definitions, and more sophisticated writing about people, places, texts, and events.", "children": [{"id": "5224a59d-8808-4726-b1b7-2ecb3d8fd7c4", "type": "subtopic", "title": "Que, quien, and lo que", "children": [{"id": "75b76a46-ede2-4db0-aad1-1435250afa66", "type": "concept", "title": "defining clauses"}, {"id": "8d383fc7-11fd-4659-92b4-79aefe7a0824", "type": "concept", "title": "non-defining clauses"}, {"id": "2ffaaa2f-3e9f-43be-b442-1a860a3b120e", "type": "concept", "title": "personal antecedents"}, {"id": "bb7eedd2-9369-4c1e-b0b0-dad530c56fd1", "type": "concept", "title": "idea reference"}], "description": "Distinguish basic connectors for things, people, and abstract ideas."}, {"id": "62497040-8e2a-4e2e-b6e6-a268a02dbb23", "type": "subtopic", "title": "El que, la que, los que, las que", "children": [{"id": "e862e02a-c50d-4569-be8f-f36e41acff28", "type": "concept", "title": "preposition + article + que"}, {"id": "bee9ac8e-2f3c-4d87-9131-005e77a0a478", "type": "concept", "title": "selection and contrast"}, {"id": "e102ee07-c649-4200-9462-95c3460474d3", "type": "concept", "title": "avoidance of ambiguity"}], "description": "Use article-based relative pronouns to clarify reference after prepositions or in contrastive contexts."}, {"id": "eb8fe713-6bae-4b80-b2c6-2ca7562ed463", "type": "subtopic", "title": "Cuyo and cual in academic style", "children": [{"id": "f3d8cc20-9d50-4cf6-a911-57e811b8d26c", "type": "concept", "title": "cuyo agreement"}, {"id": "e9a7519c-58ae-44f5-b52b-83f64d20b7f8", "type": "concept", "title": "el cual forms"}, {"id": "8ea8cb40-1dfa-4f93-ae70-d179c4f4f429", "type": "concept", "title": "formal register"}, {"id": "b0bf49ff-da31-4961-8798-6326aa0f7d15", "type": "concept", "title": "reading recognition"}], "description": "Recognize and practice relative forms that appear in formal reading and writing."}, {"id": "b7fb1cf8-22b5-40cf-b9ab-ccf39bd28d6a", "type": "subtopic", "title": "Sentence expansion and editing", "children": [{"id": "b245ef53-7408-4faf-b976-4278e1d07d5b", "type": "concept", "title": "sentence combining"}, {"id": "f3c06ed3-dd6d-421c-9656-6272e56408c1", "type": "concept", "title": "comma use"}, {"id": "8ba85cdc-581a-4c61-aac0-dbc8706a8e93", "type": "concept", "title": "paragraph flow"}, {"id": "0999645a-8ae5-41f7-abb2-99ce98a67e3c", "type": "concept", "title": "revision for style"}], "description": "Combine short sentences into cohesive paragraphs without losing clarity."}]}, {"id": "8cd7f7de-5a19-4b56-b030-8a06f0ce1e07", "type": "topic", "title": "Narration and Description", "description": "Students integrate past tenses, connectors, descriptive language, and point of view to tell compelling stories. The unit emphasizes oral storytelling, short written narratives, and culturally situated accounts rather than isolated grammar drills.", "children": [{"id": "30c8f6d0-1f5d-4a8d-b2e3-9d0cad9d7652", "type": "subtopic", "title": "Story structure", "children": [{"id": "5927de11-17de-493c-97e1-15b70b261ce7", "type": "concept", "title": "orientation"}, {"id": "d34877a4-c6ae-4c6d-9665-e2d534f2f998", "type": "concept", "title": "complication"}, {"id": "e6463db4-3c36-4fa1-a3ae-9ef453afc3c0", "type": "concept", "title": "climax"}, {"id": "86189332-59e3-4285-a508-b56ad86f50ea", "type": "concept", "title": "reflection"}], "description": "Organize narratives with a beginning, conflict, development, and resolution."}, {"id": "d2a70afd-7fd4-48bc-a4ad-57067f991017", "type": "subtopic", "title": "Description of people, places, and emotions", "children": [{"id": "a54efe02-4607-445f-8cf9-414683fed087", "type": "concept", "title": "physical description"}, {"id": "12dbafd1-5933-4a81-a5e3-974e3c13eaca", "type": "concept", "title": "personality"}, {"id": "e8d064cc-6b56-4586-945a-9a2b2b00ad8e", "type": "concept", "title": "setting"}, {"id": "e0f6b7e3-3ca5-4498-b15e-3112255a737f", "type": "concept", "title": "mood"}], "description": "Make scenes vivid with adjectives, comparisons, sensory detail, and emotional vocabulary."}, {"id": "86699e36-8d50-461e-a6c0-aa492e1db7da", "type": "subtopic", "title": "Connectors and discourse markers", "children": [{"id": "7e873f45-e1aa-4148-9a9c-894a321094b6", "type": "concept", "title": "primero"}, {"id": "094bd148-91bb-4883-b67f-04f2c7ded459", "type": "concept", "title": "mientras"}, {"id": "29fdb5e7-41fb-471c-9065-1871937ba6e9", "type": "concept", "title": "de repente"}, {"id": "a06606fd-cee3-4d31-9490-2e72ed4bf141", "type": "concept", "title": "sin embargo"}, {"id": "492a4014-f4c4-4357-9aba-5be126e382c4", "type": "concept", "title": "al final"}], "description": "Create flow between events, explanations, and reflections."}, {"id": "4a386f3a-6685-490a-b46d-227e9062e027", "type": "subtopic", "title": "Oral performance and feedback", "children": [{"id": "ac6522ae-8fd7-4563-95b9-2b4198c75eab", "type": "concept", "title": "rehearsed storytelling"}, {"id": "5a2d8373-6305-432a-9491-75f847d8034a", "type": "concept", "title": "peer questions"}, {"id": "86e28357-e3c2-41c3-a4c6-233c210d8149", "type": "concept", "title": "pronunciation targets"}, {"id": "0d939738-fbbb-4aca-ba5b-c05abbadc074", "type": "concept", "title": "self-reflection"}], "description": "Practice speaking for fluency, accuracy, pronunciation, and audience engagement."}]}, {"id": "d060c9f0-d989-44af-8837-96416b5d8908", "type": "topic", "title": "Current Events Vocabulary", "description": "This unit expands students' ability to talk about the contemporary Spanish-speaking world. Vocabulary is tied to authentic news, social issues, cultural debates, and civic language so students can discuss real topics with care.", "children": [{"id": "d8b15351-e969-4cc9-982b-11fb85e2f9e5", "type": "subtopic", "title": "News and media language", "children": [{"id": "ee3a4ff2-98ff-43a6-9cdd-743e6fc2935c", "type": "concept", "title": "titulares"}, {"id": "f5169a8a-1d6f-4010-9166-958efa691bf7", "type": "concept", "title": "fuentes"}, {"id": "c2907332-064b-4e8e-b00a-097fa81d0406", "type": "concept", "title": "reportajes"}, {"id": "dd60fb2b-fa9e-43db-b7d5-87f936e2921f", "type": "concept", "title": "opiniones"}], "description": "Build vocabulary for reading headlines, summaries, interviews, and short articles."}, {"id": "aee6f16f-373a-4111-b7a5-2dcb03537d35", "type": "subtopic", "title": "Society, politics, and community", "children": [{"id": "bf27b682-947c-449f-8311-f2fce5fdbc00", "type": "concept", "title": "gobierno"}, {"id": "25ab1f3c-b92a-448b-9e7e-6fc4a2a7b577", "type": "concept", "title": "elecciones"}, {"id": "ac3387f4-a7f0-4546-bcbe-f20b6be62549", "type": "concept", "title": "migracion"}, {"id": "af64dfe3-8ef9-4153-a6cb-46a45b5dff1a", "type": "concept", "title": "educacion"}, {"id": "0575ea00-0142-4d8d-9a5d-71e2b3ce40f0", "type": "concept", "title": "salud"}], "description": "Discuss public life using precise and respectful language."}, {"id": "431db640-78ad-488e-9024-a5bc4d007d5e", "type": "subtopic", "title": "Environment, technology, and work", "children": [{"id": "590200a4-c738-406a-95c5-593854965aaa", "type": "concept", "title": "cambio climatico"}, {"id": "2999d363-8a8e-4719-b1ec-bcd932df0e40", "type": "concept", "title": "redes sociales"}, {"id": "49e2e9ed-5f50-48b8-845a-d0471c6c055d", "type": "concept", "title": "empleo"}, {"id": "81c8c4e8-49a8-49d9-927c-d3ad86c47a8d", "type": "concept", "title": "innovacion"}], "description": "Connect intermediate Spanish to topics students encounter across the university."}, {"id": "fda1c7e7-dd18-4e69-9079-cb857715e0d6", "type": "subtopic", "title": "Vocabulary learning systems", "children": [{"id": "c692953c-cd32-45bc-aadf-dbc32e2d558d", "type": "concept", "title": "word families"}, {"id": "528ea964-7f45-4269-9b7a-28140ae0b748", "type": "concept", "title": "collocations"}, {"id": "34b61ca0-2e9a-4c26-a155-9a0cc4f0d78d", "type": "concept", "title": "personal glossary"}, {"id": "a2d2ed8e-b1d2-47a2-8c5a-ff6a4a2dcabb", "type": "concept", "title": "spaced review"}], "description": "Learn durable methods for retaining vocabulary and using it productively."}]}, {"id": "e0fc258c-f296-4a33-902c-e619668f3b24", "type": "topic", "title": "Reading Short Prose", "description": "Students develop strategies for reading authentic and adapted prose without stopping at every unfamiliar word. The unit bridges language study with literary, journalistic, and cultural reading expected later in the Spanish major.", "children": [{"id": "4910c307-78c1-4156-b552-69372f9a864a", "type": "subtopic", "title": "Reading strategies", "children": [{"id": "2840a23c-584b-4e15-904f-09406cc47ada", "type": "concept", "title": "skimming"}, {"id": "fee20162-2921-404b-9c1b-56df69cbab4b", "type": "concept", "title": "scanning"}, {"id": "a1e45bcd-64d2-44f8-98f6-2354d5a0673b", "type": "concept", "title": "inference"}, {"id": "e1bb7e80-453e-46c2-960b-d58c58bf1569", "type": "concept", "title": "annotation symbols"}], "description": "Use prediction, context, cognates, morphology, and annotation to understand meaning efficiently."}, {"id": "06f88d07-dd6f-4cfb-b046-52cbd1047fe0", "type": "subtopic", "title": "Short fiction and narrative journalism", "children": [{"id": "e19e9fd6-d129-425d-b225-6af6ee035887", "type": "concept", "title": "microcuentos"}, {"id": "c7983bae-adea-4b1c-8c05-e87399887ce1", "type": "concept", "title": "crónicas"}, {"id": "49e46233-aa61-4818-a70f-9edda40809c2", "type": "concept", "title": "profiles"}, {"id": "729829a5-6906-4df7-9c8b-2aa8bd10cfcd", "type": "concept", "title": "testimonios"}], "description": "Encounter voice, p